static int64_t int_power(int64_t base, int64_t exp_cm) {
    int64_t r = 0;
    int64_t cm_u = 0;
    int64_t cm_it1 = 0;
    int64_t cm_stop2 = 0;
    r = INT64_C(1);
    cm_it1 = INT64_C(0);
    cm_stop2 = exp_cm;
